package com.script.comminutioncraft.client;

import com.script.comminutioncraft.machine.FuelMachineMenu;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Inventory;

/**
 * GUI for tier-1 machines, in the Dark Chassis style. The texture is a 256x256 sheet
 * (generated by tools/gui_dark_chassis.py):
 * background at (0,0) 176x166, flame at (176,0) 14x14, progress arrow at (176,14) 24x17.
 * <p>
 * The tier-coloured seams beside the title and the groove after "Inventory" are drawn here
 * so they fit the label widths in any language. The seams glow while the machine is burning.
 */
public class FuelMachineScreen extends AbstractContainerScreen<FuelMachineMenu> {
    private static final int TEX_SIZE = 256;

    private static final int TITLE_COLOR = 0xFFE4E6EC;
    private static final int LABEL_COLOR = 0xFF9EA4B0;
    // Coal tier colours (see CLAUDE.md "Dark Chassis")
    private static final int SEAM_OFF = 0xFF56381F;
    private static final int SEAM_ON = 0xFFFF9628;
    private static final int SEAM_ON_GLOW = 0x60FF9628;
    private static final int GROOVE_DARK = 0xFF101114;
    private static final int GROOVE_LIGHT = 0xFF484C56;
    private static final int LABEL_GAP = 4;

    private final Identifier texture;

    public FuelMachineScreen(FuelMachineMenu menu, Inventory inventory, Component title, Identifier texture) {
        super(menu, inventory, title);
        this.texture = texture;
    }

    @Override
    protected void init() {
        super.init();
        titleLabelX = (imageWidth - font.width(title)) / 2;
    }

    @Override
    public void extractBackground(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTick) {
        super.extractBackground(graphics, mouseX, mouseY, partialTick);
        int x = leftPos;
        int y = topPos;
        graphics.blit(RenderPipelines.GUI_TEXTURED, texture, x, y, 0, 0, imageWidth, imageHeight, TEX_SIZE, TEX_SIZE);

        // Fuel flame, burns down from the top
        if (menu.isLit()) {
            int flameHeight = Mth.ceil(menu.getLitProgress() * 13.0F) + 1;
            graphics.blit(RenderPipelines.GUI_TEXTURED, texture,
                    x + 56, y + 36 + 14 - flameHeight,
                    176, 14 - flameHeight,
                    14, flameHeight, TEX_SIZE, TEX_SIZE);
        }

        // Progress arrow, fills left to right
        int arrowWidth = Mth.ceil(menu.getBurnProgress() * 24.0F);
        if (arrowWidth > 0) {
            graphics.blit(RenderPipelines.GUI_TEXTURED, texture,
                    x + 79, y + 34,
                    176, 14,
                    arrowWidth, 17, TEX_SIZE, TEX_SIZE);
        }
    }

    @Override
    protected void extractLabels(GuiGraphicsExtractor graphics, int mouseX, int mouseY) {
        // Seams either side of the title: ──── Coal Granulator ────
        int seamY = titleLabelY + 3;
        int titleEnd = titleLabelX + font.width(title);
        seam(graphics, 8, titleLabelX - LABEL_GAP, seamY);
        seam(graphics, titleEnd + LABEL_GAP, imageWidth - 8, seamY);
        graphics.text(font, title, titleLabelX, titleLabelY, TITLE_COLOR, false);

        // Engraved groove after the inventory label, separating machine and player inventory
        int grooveX = inventoryLabelX + font.width(playerInventoryTitle) + LABEL_GAP;
        int grooveY = inventoryLabelY + 3;
        graphics.fill(grooveX, grooveY, imageWidth - 8, grooveY + 1, GROOVE_DARK);
        graphics.fill(grooveX, grooveY + 1, imageWidth - 8, grooveY + 2, GROOVE_LIGHT);
        graphics.text(font, playerInventoryTitle, inventoryLabelX, inventoryLabelY, LABEL_COLOR, false);
    }

    private void seam(GuiGraphicsExtractor graphics, int x0, int x1, int y) {
        if (x1 <= x0) {
            return;
        }
        if (menu.isLit()) {
            graphics.fill(x0, y - 1, x1, y, SEAM_ON_GLOW);
            graphics.fill(x0, y, x1, y + 1, SEAM_ON);
            graphics.fill(x0, y + 1, x1, y + 2, SEAM_ON_GLOW);
        } else {
            graphics.fill(x0, y, x1, y + 1, SEAM_OFF);
        }
    }
}
